%[text] # Report test and coverage
%[text] This script generates tables containing test summary and code coverage information. This script requires the `test-result.xml` and `code-coverage.xml` files in the `test-result` folder that were generated by the Build Tool.
disp("UTC " + string(datetime("now", TimeZone="UTC", Format="yyyy-MM-dd HH:mm:ss"))) %[output:48631d85]
disp(matlabRelease) %[output:6b1b054c]
current_folder = pwd;
disp("Current folder: " + current_folder) %[output:03df258c]

% Check that the "test-result" folder exists.
assert(isfolder("test-result"))

% Check that the "test-result.xml" file exists in the "test-result" folder.
test_result_filename = "test-result.xml";
test_result_file_fullpath = fullfile(current_folder, "test-result", test_result_filename);
if not(isfile(test_result_file_fullpath))
  % The buildtool can find this script and run after having removed the test-result.xml file.
  disp(test_result_filename + " was not found.")

  return

end  % if

% Check that the "code-coverage.xml" file exists in the "test-result" folder.
code_coverage_filename = "code-coverage.xml";
code_coverage_file_fullpath = fullfile(current_folder, "test-result", code_coverage_filename);
if not(isfile(code_coverage_file_fullpath))
  % The buildtool can find this script and run after having removed the code-coverage.xml file.
  disp(code_coverage_filename + " was not found.")

  return

end  % if

matlab_paths = split(string(path), ";");
if not(any(endsWith(matlab_paths, "TestUtil")))
  addpath("TestUtil")
end  % if
test_summary_table = TestUtil1.summarizeTestResult(test_result_file_fullpath);
code_coverage_summary_struct = TestUtil1.summarizeCodeCoverage(code_coverage_file_fullpath);

disp("Test top folder: " + code_coverage_summary_struct.TotalCoverageTable.Properties.CustomProperties.TopFolder) %[output:8952e736]

disp(test_summary_table.Properties.CustomProperties) %[output:81ba88d0]
disp("Slow tests:") %[output:64423e2a]
disp(head(test_summary_table, min(50, height(test_summary_table)))) %[output:9fe8f0f5]

disp(code_coverage_summary_struct.TotalCoverageTable) %[output:2a0edb4c]
disp(code_coverage_summary_struct.ComponentCoverageTable) %[output:42ec8c35]
disp("Low-coverage code files:") %[output:77b36684]
disp(head(code_coverage_summary_struct.FileCoverageTable, min(50, height(code_coverage_summary_struct.FileCoverageTable)))) %[output:2abb83d5]
